@createArray(
    'customers.csv',
    'products.csv',
    concat(
        'orders_',
        formatDateTime(
            convertFromUtc(
                pipeline().TriggerTime,
                'India Standard Time'
            ),
            'yyyyMMdd'
        ),
        '.csv'
    ),
    concat(
        'payments_returns_',
        formatDateTime(
            convertFromUtc(
                pipeline().TriggerTime,
                'India Standard Time'
            ),
            'yyyyMMdd'
        ),
        '.csv'
    )
)

@and(
    and(activity('Get Metadata of customers').output.exists,activity('Get Metadata of orders').output.exists),

and(activity('Get Metadata of payment_returns').output.exists,activity('Get Metadata of products').output.exists)
)
